import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { NAV } from '@/constants/testIds/portfolio';
import { CHANNEL_URL } from '@/data/films';

const links = [
  { label: 'Work', href: '#work', id: NAV.linkWork },
  { label: 'About', href: '#about', id: NAV.linkAbout },
  { label: 'Services', href: '#services', id: NAV.linkServices },
  { label: 'Contact', href: '#contact', id: NAV.linkContact },
];

export const Navbar = () => {
  const [scrolled, setScrolled] = useState(false);
  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 40);
    window.addEventListener('scroll', onScroll);
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <motion.header
      initial={{ y: -80, opacity: 0 }}
      animate={{ y: 0, opacity: 1 }}
      transition={{ duration: 0.8, delay: 0.2, ease: [0.16, 1, 0.3, 1] }}
      className="fixed top-0 left-0 right-0 z-[100]"
    >
      <div
        className={`flex items-center justify-between px-6 md:px-12 py-5 transition-[background-color,backdrop-filter,border-color] duration-500 border-b ${
          scrolled
            ? 'bg-black/60 backdrop-blur-xl border-white/5'
            : 'bg-transparent border-transparent'
        }`}
      >
        <a href="#top" data-testid={NAV.brand} className="flex items-center gap-2 group">
          <span className="inline-block w-2 h-2 bg-[#E11D48] group-hover:scale-150 transition-transform duration-300" />
          <span className="font-display font-semibold text-sm tracking-[0.25em] uppercase">
            Stupid Studios
          </span>
        </a>

        <nav className="hidden md:flex items-center gap-10">
          {links.map((l) => (
            <a
              key={l.label}
              href={l.href}
              data-testid={l.id}
              className="relative text-xs tracking-[0.2em] uppercase text-white/70 hover:text-white transition-colors duration-300 after:absolute after:-bottom-1 after:left-0 after:h-px after:w-0 after:bg-[#E11D48] hover:after:w-full after:transition-all after:duration-300"
            >
              {l.label}
            </a>
          ))}
        </nav>

        <a
          href={CHANNEL_URL}
          target="_blank"
          rel="noopener noreferrer"
          data-testid={NAV.cta}
          className="text-xs tracking-[0.2em] uppercase border border-white/20 px-5 py-2.5 hover:bg-[#E11D48] hover:border-[#E11D48] transition-colors duration-300"
        >
          Subscribe
        </a>
      </div>
    </motion.header>
  );
};
